+/** @brief 严格校验 SHA-256 字符串是否为恰好 64 个小写十六进制字符（与 Forward valid_hash 一致）。 */
+static bool is_valid_sha256_hex(const std::string& sha) {
+    if (sha.size() != 64U) return false;
+    for (char ch : sha) {
+        const bool lower = (ch >= 'a' && ch <= 'f');
+        const bool digit = (ch >= '0' && ch <= '9');
+        if (!lower && !digit) return false;
+    }
+    return true;
+}
