257	/** @brief 向 DeviceInterface 发送 EmergencyStop 请求并区分 BACKEND_BUSY 与 CONFIRMED。 */
258	AisocEstopResult execute_dm_estop(aisoc_dbus_conn_t* conn, bool engage, int32_t timeout_ms) {
259	    AisocEstopResult res;
260	    res.engage = engage;
261	    if (conn == nullptr) { res.detail = "D-Bus 未连接"; return res; }
262	    const aisoc_dbus_method_call_t call = {
263	        AISOC_DBUS_BUS_NAME_DEVICE, AISOC_DBUS_PATH_DEVICE, AISOC_DBUS_IFACE_DEVICE, "EmergencyStop"};
264	    aisoc_dbus_msg_t req = {}, reply = {};
265	    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) {
266	        res.outcome = AisocEstopOutcome::FAILED;
267	        res.detail = "构造急停请求失败";
268	        return res;
269	    }
270	    aisoc_dbus_msg_append_byte(&req, engage ? 1U : 0U);
271	    const aisoc_dbus_call_opts_t opts = {timeout_ms > 800 ? timeout_ms : 800, true};
272	    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
273	    aisoc_dbus_msg_unref(&req);
274	    if (st != AISOC_DBUS_OK) {
275	        res.error_code = static_cast<int32_t>(st);
276	        res.outcome = (st == AISOC_DBUS_ERR_DISCONNECTED || st == AISOC_DBUS_ERR_INTERNAL)
277	                          ? AisocEstopOutcome::DISCONNECTED : AisocEstopOutcome::FAILED;
278	        res.detail = (res.outcome == AisocEstopOutcome::DISCONNECTED) ? "后台服务未连接" : "急停 RPC 超时或失败";
279	        return res;
280	    }
281	    aisoc_dbus_iter_t it = {};
282	    aisoc_dbus_iter_init(&reply, &it);
283	    int32_t err_code = -1;
284	    const bool got = aisoc_dbus_iter_get_int32(&it, &err_code) == AISOC_DBUS_OK;
285	    aisoc_dbus_msg_unref(&reply);
286	    if (!got) { res.outcome = AisocEstopOutcome::FAILED; res.detail = "急停应答格式异常"; return res; }
287	    res.error_code = err_code;
288	    if (err_code == 0) {
289	        res.outcome = AisocEstopOutcome::CONFIRMED;
290	        res.detail = engage ? "设备已确认急停" : "设备已解除急停";
291	    } else if (err_code == -5) {
292	        res.outcome = AisocEstopOutcome::BACKEND_BUSY;
293	        res.detail = "后台已锁定 (BUSY)";
294	    } else {
295	        res.outcome = AisocEstopOutcome::FAILED;
296	        res.detail = "设备急停请求被拒绝或超时";
297	    }
298	    return res;
299	}
