307	/** @brief 严格解析十进制无符号 64 位任务编号，拒绝空串或非数字后缀。 */
308	bool parse_u64_strict(const std::string& text, uint64_t* out_val) {
309	    if (text.empty() || out_val == nullptr) return false;
310	    char* endp = nullptr;
311	    const unsigned long long val = std::strtoull(text.c_str(), &endp, 10);
312	    if (endp == text.c_str() || *endp != '\0') return false;
313	    *out_val = static_cast<uint64_t>(val);
314	    return true;
315	}
