323	/** @brief 校验新到达的 DDS OTA 样本是否满足单调任务号/事件号且未被已超时任务污染。 */
324	bool should_accept_ota_sample(const AisocOtaStatus& cur, const std::string& tracked_tid,
325	                              const AisocOtaStatus& incoming) {
326	    if (incoming.task_id.empty()) return false;
327	    uint64_t in_tid = 0U, trk_tid = 0U, cur_tid = 0U;
328	    if (!tracked_tid.empty() && incoming.task_id != tracked_tid) {
329	        if (!parse_u64_strict(incoming.task_id, &in_tid) || !parse_u64_strict(tracked_tid, &trk_tid)) {
330	            return false;
331	        }
332	        if (in_tid < trk_tid) return false;
333	    }
334	    if (cur.task_id.empty()) return true;
335	    if (incoming.task_id == cur.task_id) {
336	        if (cur.error == "OTA_DDS_TIMEOUT") return false;
337	        return incoming.event_id > cur.event_id;
338	    }
339	    return parse_u64_strict(cur.task_id, &cur_tid) &&
340	           parse_u64_strict(incoming.task_id, &in_tid) && (in_tid > cur_tid);
341	}
