343	/** @brief 在 OtaCommand RPC 受理成功瞬间立即进入在途 PRECHECK 并清空双板展示摘要（对齐 Forward 重置行为）。 */
344	void apply_accepted_ota_rpc(const AisocOtaRequest& req, uint64_t req_seq,
345	                            const std::string& tid, AisocOtaStatus* next) {
346	    if (next == nullptr) return;
347	    next->task_id = tid;
348	    next->client_req_seq = req_seq;
349	    next->event_id = 0U;
350	    next->phase = "PRECHECK";
351	    next->active = true;
352	    next->progress_pct = 0U;
353	    next->target_mask = req.target_mask;
354	    next->reboot_verified = false;
355	    next->error.clear();
356	    next->mc = AisocOtaNodeInfo{};
357	    next->th = AisocOtaNodeInfo{};
358	}
