670	void AisocConnection::process_pending_ota() {
671	    while (true) {
672	        QueuedOtaRequest item;
673	        {
674	            std::lock_guard<std::mutex> lock(mutex_);
675	            if (stop_requested_ || ota_queue_.empty()) return;
676	            item = ota_queue_.front();
677	            ota_queue_.erase(ota_queue_.begin());
678	        }
679	        if (!config_.disable_ota_dds) {
680	            ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
681	        }
682	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
683	        uint64_t task_id = 0U;
684	        const int32_t rc = execute_fwd_ota_command(conn, item.request, config_.rpc_timeout_ms, &task_id);
685	        AisocOtaStatus next;
686	        {
687	            std::lock_guard<std::mutex> lock(mutex_);
688	            next = ota_status_;
689	            next.last_rpc_code = rc;
690	            if (rc == 0) {
691	                tracked_task_id_ = std::to_string(task_id);
692	                tracked_req_seq_ = item.req_seq;
693	                tracked_ota_op_ = item.request.operation;
694	                ota_last_activity_tp_ = std::chrono::steady_clock::now();
695	                pending_reboot_verify_ = false;
696	                apply_accepted_ota_rpc(item.request, item.req_seq, tracked_task_id_, &next);
697	            } else {
698	                const int32_t eff_rc = (conn == nullptr) ? -100 : rc;
699	                if (eff_rc != -5 || !ota_status_.active) {
700	                    tracked_task_id_.clear();
701	                    tracked_req_seq_ = 0U;
702	                    pending_reboot_verify_ = false;
703	                }
704	                apply_failed_ota_rpc(item.request, item.req_seq, eff_rc, &next);
705	            }
706	        }
707	        emit_ota_status(next);
708	    }
709	}
