711	void AisocConnection::check_ota_dds_timeout() {
712	    AisocOtaStatus timed_out;
713	    bool did_timeout = false;
714	    {
715	        std::lock_guard<std::mutex> lock(mutex_);
716	        if (ota_status_.active && ota_last_activity_tp_.time_since_epoch().count() > 0) {
717	            const uint32_t limit_ms = (!tracked_task_id_.empty() && tracked_ota_op_ == 0U)
718	                ? (config_.ota_scan_timeout_ms > 0U ? config_.ota_scan_timeout_ms : 3000U)
719	                : (config_.ota_active_timeout_ms > 0U ? config_.ota_active_timeout_ms : 30000U);
720	            const auto elapsed = std::chrono::steady_clock::now() - ota_last_activity_tp_;
721	            if (elapsed >= std::chrono::milliseconds(limit_ms)) {
722	                timed_out = ota_status_;
723	                timed_out.active = false;
724	                timed_out.maintenance = false;
725	                timed_out.phase = "FAILED";
726	                timed_out.error = "OTA_DDS_TIMEOUT";
727	                timed_out.last_rpc_code = 0;
728	                timed_out.reboot_verified = false;
729	                timed_out.client_req_seq = !tracked_task_id_.empty() ? tracked_req_seq_ : 0U;
730	                timed_out.mc = AisocOtaNodeInfo{};
731	                timed_out.th = AisocOtaNodeInfo{};
732	                tracked_task_id_.clear();
733	                tracked_req_seq_ = 0U;
734	                pending_reboot_verify_ = false;
735	                did_timeout = true;
736	            }
737	        }
738	    }
739	    if (did_timeout) emit_ota_status(timed_out);
740	}
741	
742	void AisocConnection::poll_ota_dds() {
743	    auto* sub = config_.disable_ota_dds
744	        ? nullptr
745	        : ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
746	    if (sub == nullptr) {
747	        check_ota_dds_timeout();
748	        return;
749	    }
750	    aisoc_ota_status_t sample = {};
751	    for (uint32_t i = 0U; i < 32U; ++i) {
752	        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
753	        AisocOtaStatus parsed;
754	        if (!parse_ota_status_json(sample.json, &parsed)) continue;
755	        bool accept = false;
756	        {
757	            std::lock_guard<std::mutex> lock(mutex_);
758	            if (should_accept_ota_sample(ota_status_, tracked_task_id_, parsed)) {
759	                accept = true;
760	                const bool matched_tracked = (!tracked_task_id_.empty() && parsed.task_id == tracked_task_id_);
761	                parsed.client_req_seq = matched_tracked ? tracked_req_seq_ : 0U;
762	                if (!matched_tracked || !parsed.active) {
763	                    tracked_task_id_.clear();
764	                    tracked_req_seq_ = 0U;
765	                }
766	                if (parsed.active) ota_last_activity_tp_ = std::chrono::steady_clock::now();
767	                parsed.last_rpc_code = 0;
768	                parsed.reboot_verified = false;
769	                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
770	            }
771	        }
772	        if (accept) emit_ota_status(parsed);
773	    }
774	    check_ota_dds_timeout();
775	}
