777	void AisocConnection::verify_pending_ota_reboot(const McuNodeInfo& dm_mc, const McuNodeInfo& dm_th) {
778	    AisocOtaStatus verified;
779	    bool newly_verified = false;
780	    {
781	        std::lock_guard<std::mutex> lock(mutex_);
782	        if (!pending_reboot_verify_ || ota_status_.phase != "SUCCEEDED") return;
783	        const uint32_t mask = ota_status_.target_mask;
784	        if (mask == 0U) return;
785	        const bool mc_ok = ((mask & 1U) == 0U) || node_reboot_verified(dm_mc, ota_status_.mc.pre_boot_id);
786	        const bool th_ok = ((mask & 2U) == 0U) || node_reboot_verified(dm_th, ota_status_.th.pre_boot_id);
787	        if (mc_ok && th_ok) {
788	            pending_reboot_verify_ = false;
789	            ota_status_.reboot_verified = true;
790	            verified = ota_status_;
791	            newly_verified = true;
792	        }
793	    }
794	    if (newly_verified) emit_ota_status(verified);
795	}
