892	bool is_ota_node_pkg_ready(const AisocOtaNodeInfo& info) {
893	    return info.scan_state == "READY" && info.valid && is_valid_sha256_hex(info.sha256);
894	}
895	
896	AisocOtaGateVerdict check_ota_scan_gate(bool has_conn, const AisocOtaStatus& st, const AisocSnapshot& snap) {
897	    if (!has_conn) return AisocOtaGateVerdict::DISCONNECTED;
898	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
899	    // DDS 失联超时后放行向 Forward 发起只读重扫核对权威状态；若真实维护仍在途则由 Forward 权威返回 -5 BUSY。
900	    const bool timeout_reprobe = (!st.active) && (st.error == "OTA_DDS_TIMEOUT");
901	    if (st.active || (snap.maintenance_locked && !mc_recovery && !timeout_reprobe)) {
902	        return AisocOtaGateVerdict::BACKEND_BUSY;
903	    }
904	    return AisocOtaGateVerdict::ALLOW;
905	}
906	
907	AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
908	                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
909	    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
910	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
911	    if (st.active || (snap.maintenance_locked && !mc_recovery)) {
912	        return AisocOtaGateVerdict::BACKEND_BUSY;
913	    }
914	    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
915	    const bool mc_ready = ((mask & 1U) == 0U) || is_ota_node_pkg_ready(st.mc);
916	    const bool th_ready = ((mask & 2U) == 0U) || is_ota_node_pkg_ready(st.th);
917	    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
918	    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
919	    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
920	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
921	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
922	    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
923	    return AisocOtaGateVerdict::ALLOW;
924	}
925	
926	AisocScanFeedback evaluate_ota_scan_feedback(uint64_t pending_scan_seq, const AisocOtaStatus& st) {
927	    if (pending_scan_seq == 0U || st.client_req_seq != pending_scan_seq) {
928	        return AisocScanFeedback::NONE;
929	    }
930	    if (st.last_rpc_code < 0) {
931	        return (st.error == "RPC_DISCONNECTED") ? AisocScanFeedback::ERROR : AisocScanFeedback::WARNING;
932	    }
933	    const bool scan_done = (!st.active) && (st.phase == "READY" || st.phase == "FAILED");
934	    if (!scan_done) return AisocScanFeedback::NONE;
935	    return (st.phase == "READY") ? AisocScanFeedback::SUCCESS : AisocScanFeedback::WARNING;
936	}
937	
938	AisocScanFeedback consume_ota_scan_feedback(bool* io_pending, uint64_t* io_pending_seq,
939	                                            const AisocOtaStatus& callback_ev) {
940	    if (io_pending == nullptr || io_pending_seq == nullptr || !(*io_pending)) {
941	        return AisocScanFeedback::NONE;
942	    }
943	    const AisocScanFeedback fb = evaluate_ota_scan_feedback(*io_pending_seq, callback_ev);
944	    if (fb != AisocScanFeedback::NONE) {
945	        *io_pending = false;
946	        *io_pending_seq = 0U;
947	    }
948	    return fb;
949	}
950	
951	AisocOtaLockState evaluate_ota_lock_state(const AisocOtaStatus& st, const AisocSnapshot& snap) {
952	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
953	    const bool busy = st.active || (st.last_rpc_code == -5) || (snap.maintenance_locked && !mc_recovery);
954	    if (busy) return AisocOtaLockState::BUSY;
955	    if (snap.estop_confirmed) return AisocOtaLockState::ESTOP_CONFIRMED;
956	    if (snap.estop_latched) return AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED;
957	    if (!snap.dm_connected) return AisocOtaLockState::DISCONNECTED;
958	    if (mc_recovery) return AisocOtaLockState::MC_RECOVERY;
959	    if (!snap.mc.online || !snap.th.online) return AisocOtaLockState::NODE_OFFLINE;
960	    return AisocOtaLockState::READY;
961	}
