 71	/** @brief 格式化真实 DDS OTA 阶段、校验策略、实测进度与重启核验提示（严禁前端假进度）。 */
 72	static std::string format_ota_phase(const helix::aisoc::AisocOtaStatus& st) {
 73	    if (st.last_rpc_code < 0) {
 74	        if (st.last_rpc_code == -5 || st.error == "BACKEND_BUSY") {
 75	            return "状态: 后台已锁定 (BUSY)";
 76	        }
 77	        if (st.error == "RPC_DISCONNECTED") {
 78	            return "状态: 本地服务未连接（请检查后台服务后重试）";
 79	        }
 80	        const std::string rpc_err = st.error.empty() ? std::string("OTA_COMMAND_REJECTED") : st.error;
 81	        return "升级失败: " + rpc_err + "（请核对设备在线状态与故障原因后重扫重试）";
 82	    }
 83	    if (st.error == "BACKEND_BUSY") {
 84	        return "状态: 后台已锁定 (BUSY)";
 85	    }
 86	    if (st.phase == "IDLE" && st.error == "RESTORE_MC_BEFORE_TH") {
 87	        return "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC";
 88	    }
 89	    if (st.phase == "IDLE" && st.error.empty()) {
 90	        return "等待扫描本地固件（请点击“扫描固定目录固件”检查 /run/printer-soc/firmware/）";
 91	    }
 92	    if (st.phase == "SUCCEEDED") {
 93	        if (st.reboot_verified) {
 94	            return "100% 升级完成，已回 App 且核验通过（可切回“关于”页复查版本）";
 95	        }
 96	        return "传输已提交，等待重启回 App(Bit31=0) 并核验版本与 boot_id...";
 97	    }
 98	    if (st.phase == "READY") {
 99	        // 按后端真实上报的编译期 policy 展示对应通过提示，消除硬编码验签误导。
100	        if (st.policy == "signature-required") {
101	            return "固件包签名与完整性校验通过，请确认目标与安全开关后开始升级";
102	        }
103	        return "固件包完整性校验通过，请确认目标与安全开关后开始升级";
104	    }
105	    if (st.phase == "FAILED" || (st.phase == "IDLE" && !st.error.empty())) {
106	        if (st.error == "PACKAGE_MISSING") {
107	            if (helix::aisoc::is_ota_node_pkg_ready(st.mc) || helix::aisoc::is_ota_node_pkg_ready(st.th)) {
108	                return "已找到单板可升级固件包，缺失节点请放入固件后重扫或取消选择该板";
109	            }
110	            return "固定目录未找到可升级固件包，请放入 fw_th.bin / fw_mc.bin 后重新扫描";
111	        }
112	        if (st.error == "PACKAGE_INVALID_OR_CHANGED" || st.error == "PACKAGE_SIGNATURE_INVALID") {
113	            return "固件包校验未通过，请核对节点提示并替换有效包后重新扫描";
114	        }
115	        const std::string err = st.error.empty() ? std::string("UNKNOWN") : st.error;
116	        return "升级失败: " + err + "（请核对设备在线状态与故障原因后重扫重试）";
117	    }
118	    char buf[192] = {};
119	    std::snprintf(buf, sizeof(buf), "升级进行中请勿断电：阶段 %s (%u%%)", st.phase.c_str(), st.progress_pct);
120	    return std::string(buf);
121	}
