243	void OtaLocalOverlay::handle_scan() {
244	#ifdef HELIX_ENABLE_AISOC
245	    auto* conn = helix::aisoc::active_aisoc_connection();
246	    const auto st = conn ? conn->ota_status() : helix::aisoc::AisocOtaStatus{};
247	    const auto snap = conn ? conn->snapshot() : helix::aisoc::AisocSnapshot{};
248	    const auto verdict = helix::aisoc::check_ota_scan_gate(conn != nullptr, st, snap);
249	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
250	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
251	        return;
252	    }
253	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
254	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
255	        return;
256	    }
257	    helix::aisoc::AisocOtaRequest req;
258	    req.operation = 0U;
259	    req.target_mask = 3U;
260	    pending_scan_seq_ = conn->request_ota(req);
261	    scan_feedback_pending_ = (pending_scan_seq_ != 0U);
262	#endif
263	}
