   248	/**
   249	 * @brief 在 MC 与 TH 双板均返回 4B ACK 确认后置位 estop_confirmed 并推进快照世代号
   250	 * @param state 设备管理服务状态结构体指针
   251	 */
   252	static void confirm_emergency_stop(device_manager_state_t* state) {
   253	    if (state == nullptr) return;
   254	    pthread_mutex_lock(&state->state_mutex);
   255	    if (state->estop_latched) {
   256	        state->estop_confirmed = true;
   257	        state->generation_id += 1U;
   258	        state->snapshot.generation_id = state->generation_id;
   259	    }
   260	    pthread_mutex_unlock(&state->state_mutex);
   261	}
