   263	/**
   264	 * @brief 在急停解除请求进入下游转发前撤销双板确认态，防止半程解除超时时误报双板仍确认急停
   265	 * @param state 设备管理服务状态结构体指针
   266	 */
   267	static void unconfirm_emergency_stop(device_manager_state_t* state) {
   268	    if (state == nullptr) return;
   269	    pthread_mutex_lock(&state->state_mutex);
   270	    if (state->estop_latched && state->estop_confirmed) {
   271	        state->estop_confirmed = false;
   272	        state->generation_id += 1U;
   273	        state->snapshot.generation_id = state->generation_id;
   274	    }
   275	    pthread_mutex_unlock(&state->state_mutex);
   276	}
