   278	/**
   279	 * @brief 调用下游 ForwardInterface.EmergencyStop 转发急停请求并提取首跳发送前 BUSY 拒绝证明
   280	 * @param conn D-Bus 连接指针
   281	 * @param reason_code 急停动作码（1=锁存，0=解除）
   282	 * @param out_pre_send_rejected 输出是否由下游 detail 证明首跳 MC (0x02) 未发送即被 BUSY 拒绝
   283	 * @return int32_t 双板均应答成功返回 0，否则返回对应负错误码
   284	 */
   285	static int32_t forward_emergency_stop_rpc(
   286	    aisoc_dbus_conn_t* conn,
   287	    uint8_t reason_code,
   288	    bool* out_pre_send_rejected
   289	) {
   290	    if (out_pre_send_rejected != nullptr) *out_pre_send_rejected = false;
   291	    if (conn == nullptr) return AISOC_DEV_ERR_DBUS_INIT;
   292	    aisoc_dbus_method_call_t call = {
   293	        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "EmergencyStop"
   294	    };
   295	    aisoc_dbus_msg_t fwd_req, fwd_reply;
   296	    aisoc_dbus_msg_init_call(&call, &fwd_req);
   297	    aisoc_dbus_msg_append_byte(&fwd_req, reason_code);
   298	    aisoc_dbus_call_opts_t fwd_opts = { 600, true };
   299	    const aisoc_dbus_status_t fwd_st = aisoc_dbus_call_method(conn, &fwd_req, &fwd_opts, &fwd_reply);
   300	    aisoc_dbus_msg_unref(&fwd_req);
   301	    if (fwd_st != AISOC_DBUS_OK) return (int32_t)fwd_st;
   302	    int32_t fwd_err = AISOC_DEV_ERR_FAULT;
   303	    const char* detail = nullptr;
   304	    aisoc_dbus_iter_t r_iter;
   305	    aisoc_dbus_iter_init(&fwd_reply, &r_iter);
   306	    if (aisoc_dbus_iter_get_int32(&r_iter, &fwd_err) != AISOC_DBUS_OK) {
   307	        fwd_err = AISOC_DEV_ERR_FAULT;
   308	    } else if (aisoc_dbus_iter_get_string(&r_iter, &detail) == AISOC_DBUS_OK && detail != nullptr &&
   309	               out_pre_send_rejected != nullptr && fwd_err == AISOC_DEV_ERR_BUSY) {
   310	        *out_pre_send_rejected = (std::strstr(detail, "target_node=0x02") != nullptr) &&
   311	                                 (std::strstr(detail, "sequence_id=0 ") != nullptr);
   312	    }
   313	    aisoc_dbus_msg_unref(&fwd_reply);
   314	    return fwd_err;
   315	}
