   317	/**
   318	 * @brief 处理 D-Bus EmergencyStop 请求：触发或清除急停锁定并转发至 ForwardService
   319	 * @param req D-Bus 请求消息指针
   320	 * @param reply D-Bus 响应消息指针
   321	 * @param user_data 用户上下文指针（指向 device_manager_state_t）
   322	 * @return aisoc_dbus_status_t 成功返回 AISOC_DBUS_OK
   323	 */
   324	static aisoc_dbus_status_t handle_emergency_stop(
   325	    const aisoc_dbus_msg_t* req,
   326	    aisoc_dbus_msg_t* reply,
   327	    void* user_data
   328	) {
   329	    if (req == nullptr || reply == nullptr || user_data == nullptr) return AISOC_DBUS_ERR_NULL_PTR;
   330	    device_manager_state_t* state = (device_manager_state_t*)user_data;
   331	    aisoc_dbus_iter_t iter;
   332	    aisoc_dbus_iter_init(req, &iter);
   333	    uint8_t reason_code = 0U;
   334	    if (aisoc_dbus_iter_get_byte(&iter, &reason_code) != AISOC_DBUS_OK || reason_code > 1U) {
   335	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_INVALID_ARG);
   336	        return AISOC_DBUS_OK;
   337	    }
   338	    pthread_mutex_lock(&state->state_mutex);
   339	    const bool in_maint = state->is_maintenance || state->ota_recovery_pending;
   340	    const bool prev_latched = state->estop_latched;
   341	    pthread_mutex_unlock(&state->state_mutex);
   342	    if (in_maint) {
   343	        aisoc_dbus_msg_append_int32(reply, AISOC_DEV_ERR_BUSY);
   344	        return AISOC_DBUS_OK;
   345	    }
   346	    const auto policy = reason_code == 0U ? dev_control_policy::CLEAR : dev_control_policy::STOP;
   347	    const int32_t admission = control_permission(state, 3U, policy);
   348	    if (admission != 0) {
   349	        aisoc_dbus_msg_append_int32(reply, admission);
   350	        return AISOC_DBUS_OK;
   351	    }
   352	    if (reason_code == 1U) latch_emergency_stop(state);
   353	    else unconfirm_emergency_stop(state);
   354	
   355	    bool pre_send_rejected = false;
   356	    const int32_t fwd_err = forward_emergency_stop_rpc(&state->dbus_conn, reason_code, &pre_send_rejected);
   357	    if (reason_code == 1U && fwd_err == 0) confirm_emergency_stop(state);
   358	    else if (reason_code == 1U && pre_send_rejected && !prev_latched) clear_emergency_stop_state(state);
   359	    if (reason_code == 0U && fwd_err == 0) clear_emergency_stop_state(state);
   360	    aisoc_dbus_msg_append_int32(reply, fwd_err);
   361	    return AISOC_DBUS_OK;
   362	}
