    26	/** @brief 格式化单颗 MCU 固定目录固件扫描状态、包信息与明确下一步提示。 */
    27	static std::string format_ota_pkg(const char* label, const helix::aisoc::AisocOtaNodeInfo& info) {
    28	    const char* name = (info.file.empty() && label != nullptr) ? label : info.file.c_str();
    29	    if (helix::aisoc::is_ota_node_pkg_ready(info)) {
    30	        char buf[160] = {};
    31	        std::snprintf(buf, sizeof(buf), "已就绪 · %s (%uB, sha:%s..)",
    32	                      name, info.size, info.sha256.substr(0, 12).c_str());
    33	        return std::string(buf);
    34	    }
    35	    if (info.scan_state == "MISSING") {
    36	        const char* target = (label != nullptr) ? label : name;
    37	        return std::string("缺失 · 未找到 ") + target +
    38	               "（请放入 /run/printer-soc/firmware/ 后重扫，或取消选择该板）";
    39	    }
    40	    if (info.scan_state == "SIGNATURE_INVALID") {
    41	        return "校验失败 · 发布签名校验未通过（请替换有效签名包后重扫）";
    42	    }
    43	    if (info.scan_state == "INVALID") {
    44	        return "校验失败 · 包完整性或板型不匹配（请替换有效包后重扫）";
    45	    }
    46	    return std::string(label != nullptr ? label : "firmware.bin") + ": 未扫描（点击下方扫描）";
    47	}
