    49	/** @brief 将统一并发/急停/连接锁状态枚举映射为经过 CJK 字库覆盖核验的标准提示文案。 */
    50	static const char* format_ota_lock_text(helix::aisoc::AisocOtaLockState state) {
    51	    using helix::aisoc::AisocOtaLockState;
    52	    switch (state) {
    53	        case AisocOtaLockState::BUSY:
    54	            return "状态: 后台已锁定 (BUSY)";
    55	        case AisocOtaLockState::ESTOP_CONFIRMED:
    56	            return "状态: 设备已确认急停";
    57	        case AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED:
    58	            return "状态: 本地急停已锁存（板卡未全部应答）";
    59	        case AisocOtaLockState::DISCONNECTED:
    60	            return "状态: 本地服务未连接（请检查后台服务后重试）";
    61	        case AisocOtaLockState::MC_RECOVERY:
    62	            return "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC";
    63	        case AisocOtaLockState::NODE_OFFLINE:
    64	            return "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）";
    65	        case AisocOtaLockState::READY:
    66	        default:
    67	            return "状态: 就绪";
    68	    }
    69	}
