 41	    const char* mc_state = rt->scan_state[0][0] != '\0' ? rt->scan_state[0] : "UNSCANNED";
 42	    const char* th_state = rt->scan_state[1][0] != '\0' ? rt->scan_state[1] : "UNSCANNED";
 43	    std::snprintf(rt->latest.json, sizeof(rt->latest.json),
