 50	        kOtaPolicy, static_cast<unsigned long long>(timestamp_ms), rt->last_sequence, rt->last_elapsed_ms,
 51	        static_cast<unsigned long long>(rt->task_id), static_cast<unsigned long long>(rt->event_id),
 52	        rt->phase, rt->active ? "true" : "false", rt->communication_error, rt->failed_node, rt->failed_command,
