 63	    pthread_mutex_lock(&rt->mutex);
 64	    rt->phase = phase;
 65	    rt->error = error;
 66	    const bool ended = std::strcmp(phase, "READY") == 0 || std::strcmp(phase, "SUCCEEDED") == 0;
 67	    if (ended || std::strcmp(phase, "FAILED") == 0) rt->active = false;
 68	    rt->event_id += 1U;
 69	    build_snapshot(rt);
 70	    std::fprintf(stderr, "[OTA_STAGE] %s\n", rt->latest.json);
 71	    std::fflush(stderr);
 72	    pthread_cond_broadcast(&rt->wake);
 73	    pthread_mutex_unlock(&rt->mutex);
 74	}
