185	/** @brief 计算基于实时时钟的毫秒级条件变量等待截止时间（匹配默认 pthread_cond_t 时钟域）。 */
186	static timespec make_realtime_deadline_ms(uint32_t delay_ms) {
187	    timespec ts = {};
188	    clock_gettime(CLOCK_REALTIME, &ts);
189	    ts.tv_sec += static_cast<time_t>(delay_ms / 1000U);
190	    ts.tv_nsec += static_cast<long>(delay_ms % 1000U) * 1000000L;
191	    if (ts.tv_nsec >= 1000000000L) {
192	        ts.tv_sec += 1;
193	        ts.tv_nsec -= 1000000000L;
194	    }
195	    return ts;
196	}
