198	/** @brief context 为服务槽；仅在 DDS 发布成功后推进 published_id，失败时有界退避重送最新终态。 */
199	static void* reporter_main(void* context) {
200	    if (context == nullptr) return nullptr;
201	    auto* rt = static_cast<fwd_ota_runtime*>(context);
202	    uint64_t retry_event_id = 0U;
203	    uint32_t retry_count = 0U;
204	    while (true) {
205	        aisoc_ota_status_t sample = {};
206	        uint64_t target_id = 0U;
207	        pthread_mutex_lock(&rt->mutex);
208	        while (rt->published_id == rt->event_id && !rt->stopping) {
209	            pthread_cond_wait(&rt->wake, &rt->mutex);
210	        }
211	        if (rt->stopping) {
212	            pthread_mutex_unlock(&rt->mutex);
213	            break;
214	        }
215	        if (rt->event_id != retry_event_id) {
216	            retry_event_id = rt->event_id;
217	            retry_count = 0U;
218	        }
219	        sample = rt->latest;
220	        target_id = rt->event_id;
221	        pthread_mutex_unlock(&rt->mutex);
222	        const auto status = aisoc_dds_publish_ota_status(rt->publisher, &sample);
223	        pthread_mutex_lock(&rt->mutex);
224	        if (status == AISOC_DDS_OK) {
225	            if (rt->published_id < target_id) rt->published_id = target_id;
226	            retry_count = 0U;
227	        } else {
228	            if (retry_count < 5U || (retry_count % 20U) == 0U) {
229	                std::fprintf(stderr, "[OTA_DDS] error_code=%d event_id=%llu retry=%u\n",
230	                             status, static_cast<unsigned long long>(target_id), retry_count + 1U);
231	            }
232	            if (retry_count < 1000U) retry_count += 1U;
233	            if (!rt->stopping && rt->event_id == target_id) {
234	                const timespec dl = make_realtime_deadline_ms(retry_count <= 20U ? 50U : 250U);
235	                pthread_cond_timedwait(&rt->wake, &rt->mutex, &dl);
236	            }
237	        }
238	        pthread_mutex_unlock(&rt->mutex);
239	    }
240	    return nullptr;
241	}
