244	static bool valid_hash(const char* text) {
245	    if (text == nullptr || std::strlen(text) != 64U) return false;
246	    for (size_t index = 0U; index < 64U; ++index) {
247	        const bool lower = text[index] >= 'a' && text[index] <= 'f';
248	        const bool digit = text[index] >= '0' && text[index] <= '9';
249	        if (!lower && !digit) return false;
250	    }
251	    return true;
252	}
