    13	uint32_t ota_read32(const uint8_t* data) {
    14	    if (data == nullptr) return 0U;
    15	    return static_cast<uint32_t>(data[0]) | (static_cast<uint32_t>(data[1]) << 8U) |
    16	        (static_cast<uint32_t>(data[2]) << 16U) | (static_cast<uint32_t>(data[3]) << 24U);
    17	}
    18	void ota_write32(uint32_t value, uint8_t* data) {
    19	    if (data == nullptr) return;
    20	    for (size_t index = 0U; index < 4U; ++index) data[index] = static_cast<uint8_t>(value >> (index * 8U));
    21	}
    22	/** @brief 将 data/size 的 SHA256 写入 output 的65B十六进制字符串；失败返回假。 */
    23	static bool hash_hex(const uint8_t* data, size_t size, char* output) {
    24	    if (data == nullptr || output == nullptr) return false;
    25	    uint8_t hash[32];
    26	    if (!fw_image_sha256(data, size, hash)) return false;
    27	    for (size_t index = 0U; index < 32U; ++index) std::snprintf(output + index * 2U, 3U, "%02x", hash[index]);
    28	    return true;
    29	}
    30	/** @brief fd 为打开的常规文件，image 为有界缓存；按 fstat 大小读取并拒绝在读期间变化的文件。 */
    31	static bool read_image(int fd, ota_image* image) {
    32	    if (image == nullptr) return false;
    33	    struct stat before = {}, after = {};
    34	    if (fstat(fd, &before) != 0 || !S_ISREG(before.st_mode)) return false;
    35	    if (before.st_size <= 128 || static_cast<uint64_t>(before.st_size) > image->capacity) return false;
    36	    size_t offset = 0U;
    37	    while (offset < static_cast<size_t>(before.st_size)) {
    38	        const auto count = read(fd, image->buffer + offset, static_cast<size_t>(before.st_size) - offset);
    39	        if (count < 0 && errno == EINTR) continue;
    40	        if (count <= 0) return false;
    41	        offset += static_cast<size_t>(count);
    42	    }
    43	    if (fstat(fd, &after) != 0 || after.st_size != before.st_size) return false;
    44	    if (after.st_mtim.tv_sec != before.st_mtim.tv_sec || after.st_mtim.tv_nsec != before.st_mtim.tv_nsec) return false;
    45	    image->size = static_cast<uint32_t>(offset - 128U);
    46	    return true;
    47	}
    48	/** @brief 记录单个节点的固定目录扫描状态码与错误详情（定长静态拷贝）。 */
    49	static void set_scan_result(fwd_ota_runtime* rt, uint8_t index, const char* state, const char* err) {
    50	    if (rt == nullptr || index > 1U) return;
    51	    std::snprintf(rt->scan_state[index], sizeof(rt->scan_state[index]), "%s", state != nullptr ? state : "");
    52	    std::snprintf(rt->scan_error[index], sizeof(rt->scan_error[index]), "%s", err != nullptr ? err : "");
    53	}
    54	/** @brief image 为稳定快照，index 为板型0/1；校验尾块、净荷摘要（及默认模式 ECDSA-P256 签名）后生成元数据。 */
    55	static bool verify_image(ota_image* image, uint8_t index, const char** out_error) {
    56	    if (image == nullptr || image->size == 0U) {
    57	        if (out_error != nullptr) *out_error = "STAT_OR_SIZE_INVALID";
    58	        return false;
    59	    }
    60	    const auto* trailer = image->buffer + image->size;
    61	    const uint32_t board = index == 0U ? 0x43500001U : 0x42300001U;
    62	    if (ota_read32(trailer) != 0x41545347U || ota_read32(trailer + 4U) != 0x00010000U) {
    63	        if (out_error != nullptr) *out_error = "TRAILER_OR_HASH_INVALID";
    64	        return false;
    65	    }
    66	    if (ota_read32(trailer + 8U) != board) {
    67	        if (out_error != nullptr) *out_error = "BOARD_ID_MISMATCH";
    68	        return false;
    69	    }
    70	    if (ota_read32(trailer + 16U) != image->size) {
    71	        if (out_error != nullptr) *out_error = "STAT_OR_SIZE_INVALID";
    72	        return false;
    73	    }
    74	    if (fw_image_crc32(trailer, 124U) != ota_read32(trailer + 124U)) {
    75	        if (out_error != nullptr) *out_error = "TRAILER_OR_HASH_INVALID";
    76	        return false;
    77	    }
    78	    uint8_t hash[32];
    79	    if (!fw_image_sha256(image->buffer, image->size, hash) || std::memcmp(hash, trailer + 20U, 32U) != 0) {
    80	        if (out_error != nullptr) *out_error = "TRAILER_OR_HASH_INVALID";
    81	        return false;
    82	    }
    83	#if !defined(AISOC_OTA_INTEGRITY_ONLY_HIL)
    84	    char pubkey_path[256];
    85	    if (!fw_image_resolve_pubkey_path(pubkey_path, sizeof(pubkey_path)) ||
    86	        !fw_image_verify_ecdsa_p256(trailer, pubkey_path)) {
    87	        if (out_error != nullptr) *out_error = "PACKAGE_SIGNATURE_INVALID";
    88	        return false;
    89	    }
    90	#else
    91	    // 仅 HIL 临时完整性候选跳过发布方 ECDSA 验签，仍保留全量 ATSG/CRC32/SHA-256 校验。
    92	    (void)out_error;
    93	#endif
    94	    image->version = ota_read32(trailer + 12U);
    95	    image->crc = fw_image_crc32(image->buffer, image->size);
    96	    if (!hash_hex(image->buffer, image->size + 128U, image->sha256)) {
    97	        if (out_error != nullptr) *out_error = "TRAILER_OR_HASH_INVALID";
    98	        return false;
    99	    }
   100	    image->valid = true;
   101	    return true;
   102	}
