   104	/** @brief 清空单个镜像槽的校验有效位、大小、版本、CRC 与 SHA-256 摘要，避免失败时残留旧元数据。 */
   105	static void reset_image_meta(ota_image* image) {
   106	    if (image == nullptr) return;
   107	    image->valid = false;
   108	    image->size = 0U;
   109	    image->crc = 0U;
   110	    image->version = 0U;
   111	    image->sha256[0] = '\0';
   112	}
   113	
   114	bool ota_load_image(fwd_ota_runtime* rt, uint8_t index) {
   115	    if (rt == nullptr || index > 1U) return false;
   116	    auto* image = &rt->image[index];
   117	    reset_image_meta(image);
   118	    rt->error = "";
   119	    set_scan_result(rt, index, "INVALID", "STAT_OR_SIZE_INVALID");
   120	    char path[512];
   121	    const char* name = index == 0U ? "fw_mc.bin" : "fw_th.bin";
   122	    const int length = std::snprintf(path, sizeof(path), "%s/%s", rt->owner->firmware_dir, name);
   123	    if (length < 0 || static_cast<size_t>(length) >= sizeof(path)) return false;
   124	    const int fd = open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
   125	    if (fd < 0) {
   126	        // 明确区分文件不存在（MISSING）与符号链接/权限等非法文件状态（INVALID）。
   127	        if (errno == ENOENT) set_scan_result(rt, index, "MISSING", "FILE_NOT_FOUND");
   128	        return false;
   129	    }
   130	    const bool read_ok = read_image(fd, image);
   131	    close(fd);
   132	    if (!read_ok) {
   133	        reset_image_meta(image);
   134	        return false;
   135	    }
   136	    const char* verify_err = nullptr;
   137	    if (!verify_image(image, index, &verify_err)) {
   138	        reset_image_meta(image);
   139	        const char* err_code = (verify_err != nullptr) ? verify_err : "TRAILER_OR_HASH_INVALID";
   140	        if (std::strcmp(err_code, "PACKAGE_SIGNATURE_INVALID") == 0) {
   141	            rt->error = "PACKAGE_SIGNATURE_INVALID";
   142	            set_scan_result(rt, index, "SIGNATURE_INVALID", err_code);
   143	        } else {
   144	            set_scan_result(rt, index, "INVALID", err_code);
   145	        }
   146	        return false;
   147	    }
   148	    if (rt->operation == 1U && std::strcmp(rt->expected[index], image->sha256) != 0) {
   149	        reset_image_meta(image);
   150	        set_scan_result(rt, index, "INVALID", "TRAILER_OR_HASH_INVALID");
   151	        return false;
   152	    }
   153	    set_scan_result(rt, index, "READY", "");
   154	    return true;
   155	}

 285	 * @brief 综合双节点温度与版本在线状态更新顶层 system_status_desc 与 device_state
 286	 * @param state 设备管理服务状态结构体指针
 287	 */
 288	static void update_system_status_desc(device_manager_state_t* state) {
 289	    if (state == nullptr || state->is_fault) {
 290	        return;
 291	    }
 292	    if (state->is_maintenance) {
 293	        strncpy(state->snapshot.system_status_desc, "UPGRADING_MAINTENANCE", sizeof(state->snapshot.system_status_desc) - 1U);
 294	        strncpy(state->device_state, "UPGRADING_MAINTENANCE", sizeof(state->device_state) - 1U);
 295	        return;
 296	    }
 297	    if (state->ota_recovery_pending) {
 298	        strncpy(state->snapshot.system_status_desc, "OTA_RECOVERY_PENDING", sizeof(state->snapshot.system_status_desc) - 1U);
 299	        strncpy(state->device_state, "OTA_RECOVERY_PENDING", sizeof(state->device_state) - 1U);
 300	        return;
 301	    }
 302	    const dev_state_version_binding_t* b = find_version_binding(state);
 303	    const bool mc_offline = state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_OFFLINE;
 304	    const bool th_offline = state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_OFFLINE;
 305	
 306	    if (mc_offline && th_offline) {
 307	        strncpy(state->snapshot.system_status_desc, "OFFLINE", sizeof(state->snapshot.system_status_desc) - 1U);
 308	        return;
 309	    }
 310	    if (mc_offline || th_offline) {
 311	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 312	        return;
 313	    }
 314	
 315	    if (!identities_ready(b)) {
 316	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 317	        return;
 318	    }
 319	    const bool b_fault = (state->snapshot.bed_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
 320	                         (state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
 321	                         (state->snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FAULT);
 322	    const bool t_fault = (state->snapshot.tool_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
 323	                         (state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
 324	                         (state->snapshot.tool_quality == (uint32_t)AISOC_QUALITY_FAULT);
 325	    if (b_fault || t_fault) {
 326	        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
 327	        return;
 373	        norm_millic = AISOC_TEMP_MILLIC_FAULT;
 374	        if (norm_status == (uint32_t)AISOC_SENSOR_OK) {
 375	            norm_status = (uint32_t)AISOC_SENSOR_OPEN;
 376	        }
 377	    }
 378	    if (sample->source_node == 1U) {
 379	        state->bed_raw_adc = sample->raw_adc;
 380	        state->bed_raw_adc_valid = true;
 381	        state->snapshot.bed_temp_millic = norm_millic;
 382	        state->snapshot.bed_sensor_status = norm_status;
 383	        state->snapshot.bed_quality = eval_sample_quality(norm_millic, norm_status);
 384	        state->last_bed_rx_ns = sample->host_received_ns;
 385	    } else if (sample->source_node == 2U) {
 386	        state->tool_raw_adc = sample->raw_adc;
 387	        state->tool_raw_adc_valid = true;
 388	        state->snapshot.tool_temp_millic = norm_millic;
 389	        state->snapshot.tool_sensor_status = norm_status;
 390	        state->snapshot.tool_quality = eval_sample_quality(norm_millic, norm_status);
 391	        state->last_tool_rx_ns = sample->host_received_ns;
 392	    }
 393	
 394	    update_system_status_desc(state);
 395	    if (out_of_range) {
 396	        state->is_fault = true;
 397	        state->non_estop_fault = true;
 398	        strncpy(state->device_state, "FAULT", sizeof(state->device_state) - 1U);
 399	    }
 400	    state->snapshot.generation_id++;
 401	    state->generation_id++;
 402	    return AISOC_DEV_OK;
 403	}
