 405	/**
 406	 * @brief 检查综合业务样本的源节点和受约束字段，防止错误 DDS 发布者绕过位图语义。
 407	 * @param status [in] 非空候选业务状态。
 408	 * @return 真表示字段范围合法，温度仍由后续通道质量门禁处理。
 409	 */
 410	static bool valid_device_status(const aisoc_device_status_t* status) {
 411	    if (status == nullptr) return false;
 412	    if (status->source_node != MINIMC_DEV_MC && status->source_node != MINIMC_DEV_SCM_TH) return false;
 413	    if ((status->validity_bitmap & ~15U) != 0U || (status->sensor_fault_bitmap & ~7U) != 0U) return false;
 414	    if (status->machine_state > 6U || status->homed_flags > 7U) return false;
 415	    if (status->fan_speed > 255U || status->feedrate_percent > 255U) return false;
 416	    return status->planner_free_slots <= 32U;
 417	}
