 425	static void apply_status_safety(device_manager_state_t* state,
 426	                                const aisoc_device_status_t* status, bool is_mc) {
 427	    if (state == nullptr || status == nullptr) return;
 428	    if (is_mc && (status->machine_state == 3U || status->machine_state == 4U)) state->is_printing = true;
