 430	    // 未知目标温度为正值哨兵，也保持保守约束；0x40 不包含 PWM，不能据此批准加热安全。
 431	    if (status->target_temperature_millic[target] > 0) state->is_heating = true;
 432	    if (is_mc && status->machine_state >= 5U) {
 433	        state->is_fault = true;
 434	        state->non_estop_fault = true;
 435	        strncpy(state->device_state, "FAULT", sizeof(state->device_state) - 1U);
 436	        strncpy(state->snapshot.system_status_desc, "FAULT", sizeof(state->snapshot.system_status_desc) - 1U);
