1202	/**
1203	 * @brief 校验 OTA 升级前四项物理安全准入条件（作业空闲、运动空闲、温度有效无故障、加热全关）
1204	 */
1205	aisoc_dev_status_t dev_state_check_ota_admission(
1206	    const device_manager_state_t* state,
1207	    const dev_ota_safety_ctx_t* safety,
1208	    dev_admission_res_t* out_res
1209	) {
1210	    if (state == nullptr || safety == nullptr || out_res == nullptr) {
1211	        return AISOC_DEV_ERR_NULL_PTR;
1212	    }
1213	    out_res->accepted = false;
1214	    const bool job_ok = !state->is_printing &&
1215	        (safety->job_state == 0U || safety->job_state == 3U || safety->job_state == 4U);
1216	    if (!job_ok) {
1217	        strncpy(out_res->reason, "OTA_REJECTED_JOB_ACTIVE", sizeof(out_res->reason) - 1U);
1218	        return AISOC_DEV_ERR_NOT_SAFE_FOR_OTA;
1219	    }
1220	    if (safety->mc_state != 0U) {
1221	        strncpy(out_res->reason, "OTA_REJECTED_MOTION_MOVING", sizeof(out_res->reason) - 1U);
1222	        return AISOC_DEV_ERR_NOT_SAFE_FOR_OTA;
1223	    }
1224	    const bool heater_off = !state->is_heating &&
1225	        (safety->target_bed_deci_c <= 0) && (safety->target_tool_deci_c <= 0) &&
1226	        (safety->bed_heater_duty == 0U) && (safety->tool_heater_duty == 0U);
1227	    if (!heater_off) {
1228	        strncpy(out_res->reason, "OTA_REJECTED_HEATER_ACTIVE", sizeof(out_res->reason) - 1U);
1229	        return AISOC_DEV_ERR_NOT_SAFE_FOR_OTA;
1230	    }
1231	    if (!safety->recovery_mode) {
1232	        const bool temp_valid =
1233	            (state->snapshot.bed_temp_millic != AISOC_TEMP_MILLIC_FAULT) &&
1234	            (state->snapshot.bed_temp_millic != AISOC_TEMP_MILLIC_OFFLINE) &&
1235	            (state->snapshot.tool_temp_millic != AISOC_TEMP_MILLIC_FAULT) &&
1236	            (state->snapshot.tool_temp_millic != AISOC_TEMP_MILLIC_OFFLINE) &&
1237	            (state->snapshot.bed_sensor_status == (uint32_t)AISOC_SENSOR_OK) &&
1238	            (state->snapshot.tool_sensor_status == (uint32_t)AISOC_SENSOR_OK);
1239	        if (!temp_valid) {
1240	            strncpy(out_res->reason, "OTA_REJECTED_TEMP_SENSOR_INVALID", sizeof(out_res->reason) - 1U);
1241	            return AISOC_DEV_ERR_NOT_SAFE_FOR_OTA;
1242	        }
1243	    }
1244	    out_res->accepted = true;
1245	    strncpy(out_res->reason, "SAFE_FOR_OTA", sizeof(out_res->reason) - 1U);
1246	    return AISOC_DEV_OK;
1247	}
