   604	void AisocConnection::worker_loop() {
   605	    while (true) {
   606	        process_pending_estops();
   607	        process_pending_ota();
   608	        poll_ota_dds();
   609	        bool do_refresh = false;
   610	        {
   611	            std::lock_guard<std::mutex> lock(mutex_);
   612	            if (stop_requested_) break;
   613	            do_refresh = refresh_requested_;
   614	            refresh_requested_ = false;
   615	        }
   616	        poll_once();
   617	        poll_ota_dds();
   618	        if (do_refresh) process_pending_estops();
   619	        std::unique_lock<std::mutex> lock(mutex_);
   620	        if (stop_requested_) break;
   621	        const uint32_t wait_ms = compute_worker_wait_ms();
   622	        cv_.wait_for(lock, std::chrono::milliseconds(wait_ms), [this]() {
   623	            return stop_requested_ || refresh_requested_ || !estop_queue_.empty() || !ota_queue_.empty();
   624	        });
   625	        if (stop_requested_) break;
   626	    }
   627	}
