   797	void AisocConnection::poll_once() {
   798	    AisocSnapshot next;
   799	    {
   800	        std::lock_guard<std::mutex> lock(mutex_);
   801	        next.ap = snapshot_.ap;
   802	        next.estop_latched = snapshot_.estop_latched;
   803	        next.estop_confirmed = snapshot_.estop_confirmed;
   804	        next.last_estop_outcome = snapshot_.last_estop_outcome;
   805	        next.last_estop_detail = snapshot_.last_estop_detail;
   806	    }
   807	    auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
   808	    if (conn == nullptr) {
   809	        next.estop_latched = false;
   810	        next.estop_confirmed = false;
   811	        next.device_state = "OFFLINE";
   812	        next.system_status = "OFFLINE";
   813	        publish_if_changed(next, false);
   814	        return;
   815	    }
   816	    std::string ver_json;
   817	    const aisoc_dbus_status_t ver_st = call_dm_string(conn, "GetVersionInfo", config_.rpc_timeout_ms, &ver_json);
   818	    if (ver_st != AISOC_DBUS_OK || !parse_dm_version_json(ver_json, &next.mc, &next.th)) {
   819	        if (ver_st == AISOC_DBUS_ERR_DISCONNECTED) close_dbus(&dbus_handle_);
   820	        next.dm_connected = false;
   821	        next.estop_latched = false;
   822	        next.estop_confirmed = false;
   823	        next.device_state = "OFFLINE";
   824	        next.system_status = "OFFLINE";
   825	        publish_if_changed(next, false);
   826	        return;
   827	    }
   828	    next.dm_connected = true;
   829	    verify_pending_ota_reboot(next.mc, next.th);
   830	    std::string snap_json, state_json;
   831	    if (call_dm_string(conn, "GetSnapshot", config_.rpc_timeout_ms, &snap_json) == AISOC_DBUS_OK) {
   832	        parse_dm_snapshot_json(snap_json, &next);
   833	    }
   834	    if (call_dm_string(conn, "GetDeviceState", config_.rpc_timeout_ms, &state_json) == AISOC_DBUS_OK) {
   835	        merge_dm_state_json(state_json, &next);
   836	    }
   837	    if (!next.mc.online) {
   838	        McuNodeInfo fwd_mc;
   839	        if (query_forward_version(conn, 1U, config_.rpc_timeout_ms, &fwd_mc)) next.mc = fwd_mc;
