   907	AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
   908	                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
   909	    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
   910	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
   911	    if (st.active || (snap.maintenance_locked && !mc_recovery)) {
   912	        return AisocOtaGateVerdict::BACKEND_BUSY;
   913	    }
   914	    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
   915	    const bool mc_ready = ((mask & 1U) == 0U) || is_ota_node_pkg_ready(st.mc);
   916	    const bool th_ready = ((mask & 2U) == 0U) || is_ota_node_pkg_ready(st.th);
   917	    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
   918	    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
   919	    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
   920	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
   921	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
   922	    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
   923	    return AisocOtaGateVerdict::ALLOW;
   924	}
