   926	AisocScanFeedback evaluate_ota_scan_feedback(uint64_t pending_scan_seq, const AisocOtaStatus& st) {
   927	    if (pending_scan_seq == 0U || st.client_req_seq != pending_scan_seq) {
   928	        return AisocScanFeedback::NONE;
   929	    }
   930	    if (st.last_rpc_code < 0) {
   931	        return (st.error == "RPC_DISCONNECTED") ? AisocScanFeedback::ERROR : AisocScanFeedback::WARNING;
   932	    }
   933	    const bool scan_done = (!st.active) && (st.phase == "READY" || st.phase == "FAILED");
   934	    if (!scan_done) return AisocScanFeedback::NONE;
