   951	AisocOtaLockState evaluate_ota_lock_state(const AisocOtaStatus& st, const AisocSnapshot& snap) {
   952	    const bool mc_recovery = is_mc_recovery_idle(st, snap);
   953	    const bool busy = st.active || (st.last_rpc_code == -5) || (snap.maintenance_locked && !mc_recovery);
   954	    if (busy) return AisocOtaLockState::BUSY;
   955	    if (snap.estop_confirmed) return AisocOtaLockState::ESTOP_CONFIRMED;
   956	    if (snap.estop_latched) return AisocOtaLockState::ESTOP_LATCHED_UNCONFIRMED;
   957	    if (!snap.dm_connected) return AisocOtaLockState::DISCONNECTED;
   958	    if (mc_recovery) return AisocOtaLockState::MC_RECOVERY;
   959	    if (!snap.mc.online || !snap.th.online) return AisocOtaLockState::NODE_OFFLINE;
   960	    return AisocOtaLockState::READY;
   961	}
