aisoc_fwd_status_t fwd_ota_command(forward_service_state_t* state,
    const fwd_ota_command_request* request, uint64_t* out_task) {
    if (state == nullptr || request == nullptr || out_task == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (state->ota == nullptr) return AISOC_FWD_ERR_BUSY;
    if (request->operation > 1U || request->target_mask < 1U || request->target_mask > 3U)
        return AISOC_FWD_ERR_INVALID_ARG;
    if (request->operation == 1U) {
        if (!request->confirmed_safe) return AISOC_FWD_ERR_INVALID_ARG;
        if ((request->target_mask & 1U) != 0U && !valid_hash(request->mc_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
        if ((request->target_mask & 2U) != 0U && !valid_hash(request->th_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
    }
    auto* rt = state->ota;
    pthread_mutex_lock(&rt->mutex);
    if (rt->active || rt->stopping) {
        pthread_mutex_unlock(&rt->mutex);
        return AISOC_FWD_ERR_BUSY;
    }
    prepare_command(rt, request);
    *out_task = rt->task_id;
