aisoc_fwd_status_t fwd_ota_service_start(forward_service_state_t* state) {
    if (state == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (runtime.owner != nullptr) return AISOC_FWD_ERR_BUSY;
    auto* rt = &runtime;
    *rt = {};
    if (pthread_mutex_init(&rt->mutex, nullptr) != 0) return AISOC_FWD_ERR_SERIAL_IO;
    if (pthread_cond_init(&rt->wake, nullptr) != 0) {
        pthread_mutex_destroy(&rt->mutex);
        return AISOC_FWD_ERR_SERIAL_IO;
    }
    rt->initialized = true;
    rt->owner = state;
    rt->phase = "IDLE";
    rt->error = "";
    rt->task_id = static_cast<uint64_t>(std::time(nullptr)) * 1000000U;
    rt->image[0] = {mc_image, sizeof(mc_image), 0U, 0U, 0U, false, {0}};
    rt->image[1] = {th_image, sizeof(th_image), 0U, 0U, 0U, false, {0}};
    std::snprintf(rt->scan_state[0], sizeof(rt->scan_state[0]), "UNSCANNED");
    std::snprintf(rt->scan_state[1], sizeof(rt->scan_state[1]), "UNSCANNED");
    state->ota = rt;
    const aisoc_dds_publisher_config_t config = {AISOC_TOPIC_OTA_STATUS, AISOC_DDS_QOS_RELIABLE_TRANSIENT_LOCAL};
    const auto status = aisoc_dds_publisher_create(state->dds_participant, &config, &rt->publisher);
    if (status != AISOC_DDS_OK) {
        fwd_ota_service_stop(state);
        return AISOC_FWD_ERR_DDS_INIT;
    }
    if (pthread_create(&rt->worker, nullptr, worker_main, rt) != 0) {
        fwd_ota_service_stop(state);
        return AISOC_FWD_ERR_SERIAL_IO;
    }
    rt->worker_started = true;
    if (pthread_create(&rt->reporter, nullptr, reporter_main, rt) != 0) {
        fwd_ota_service_stop(state);
        return AISOC_FWD_ERR_SERIAL_IO;
    }
    rt->reporter_started = true;
    ota_emit(rt, "IDLE", "");
    return AISOC_FWD_OK;
}

