void fwd_control_record_fault(forward_service_state_t* state, const fwd_ctrl_expect_t* expect,
                             uint32_t elapsed_ms, aisoc_fwd_status_t status) {
    if (state == nullptr || expect == nullptr) return;
    state->last_fault.target_node = expect->expected_src;
    state->last_fault.sequence_id = expect->expected_seq;
    state->last_fault.elapsed_ms = elapsed_ms;
    state->last_fault.error_code = static_cast<int32_t>(status);
    std::snprintf(state->last_fault.detail, sizeof(state->last_fault.detail),
        "target_node=0x%02X sequence_id=%u elapsed_ms=%u error_code=%d",
        expect->expected_src, expect->expected_seq, elapsed_ms, static_cast<int>(status));
    std::fprintf(stderr, "[FWD FAULT] %s\n", state->last_fault.detail);
}

aisoc_fwd_status_t fwd_control_exchange_locked(forward_service_state_t* state,
    const fwd_control_request* request, fwd_control_reply* output) {
    if (state == nullptr || request == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    const auto* command = find_command(request);
    if (command == nullptr || request->timeout_ms > INT32_MAX) return AISOC_FWD_ERR_INVALID_ARG;
    control_completion completion;
    const uint8_t priority = request->command == 0x17U ? MINIMC_FLAG_IS_PRIORITY : 0U;
    const fwd_exchange_spec spec = {
        {command->command, command->response, command->request_size, command->request_size,
         command->response_size, command->response_size, true, MINIMC_CMD_NACK, priority},
        {request->destination, request->command, static_cast<const uint8_t*>(request->data),
         request->size, request->timeout_ms, 0U}, on_control_event, &completion};
    const auto result = fwd_exchange_locked(state, &spec);
    const auto status = result == AISOC_FWD_OK ? completion.status : result;
    if (status != AISOC_FWD_OK) {
        const fwd_ctrl_expect_t expect = {request->destination, completion.reply.sequence_id,
            command->response, command->response, command->response_size, request->timeout_ms};
        fwd_control_record_fault(state, &expect, completion.elapsed_ms, status);
        return status;
    }
    state->last_fault = {};
    *output = completion.reply;
    return AISOC_FWD_OK;
}

/**
 * @brief 将业务响应中的拒绝状态记录为失败，不用协议收包成功替代业务成功。
 * @param state [in,out] 持 UART 锁的所有者。
 * @param request [in] 原请求。
 * @param reply [in] 成功收到的协议响应。
 * @param status [in] 业务解码或拒绝的真实错误码。
 * @return 原错误码，不合成通信成功。
 */
static aisoc_fwd_status_t record_business_failure(forward_service_state_t* state,
    const fwd_control_request* request, const fwd_control_reply* reply, aisoc_fwd_status_t status) {
    if (state == nullptr || request == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (reply == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    const fwd_ctrl_expect_t expect = {request->destination, reply->sequence_id,
        reply->frame.rx_cmd, reply->frame.rx_cmd, reply->frame.payload_len, request->timeout_ms};
    fwd_control_record_fault(state, &expect, reply->frame.elapsed_ms, status);
    return status;
}

/** @brief 目标位图只允许 MC/TH；零按现有接口表示双节点。 */
static bool valid_mask(uint8_t mask) {
    return (mask & ~0x03U) == 0U;
}

/** @brief 本次温控响应及样本；双节点部分失败时仍发布已经获得的真实样本。 */
struct temperature_result {
    minimc_temp_wire_payload_t wire = {};
    aisoc_raw_temp_t sample = {};
};

/**
 * @brief 单节点设温通过统一事务并解码为真实样本，不持锁调用 DDS。
 * @param state [in,out] 持 UART 锁的状态。
 * @param destination [in] 线缆节点 2/3。
 * @param request [in] 4B 温控请求。
 * @param output [out] 成功时写入自有响应和样本。
 * @return 实际通信或载荷解码状态。
 */
static aisoc_fwd_status_t set_temperature_node(forward_service_state_t* state,
    uint8_t destination, const minimc_set_temp_req_t* request, temperature_result* output) {
    if (state == nullptr || request == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    const fwd_control_request control = {destination, MINIMC_CMD_SET_TEMP, request, sizeof(*request), 0U};
    fwd_control_reply reply;
    auto status = fwd_control_exchange_locked(state, &control, &reply);
    if (status != AISOC_FWD_OK) return status;
    temperature_result result;
    const uint8_t logical = destination == MINIMC_DEV_MC ? 1U : 2U;
    status = fwd_proto_parse_raw_temp(reply.frame.payload, reply.frame.payload_len, logical, &result.sample);
    if (status != AISOC_FWD_OK) return record_business_failure(state, &control, &reply, status);
    result.sample.sequence_id = reply.sequence_id;
    std::memcpy(&result.wire, reply.frame.payload, sizeof(result.wire));
    *output = result;
    return AISOC_FWD_OK;
}

aisoc_fwd_status_t forward_service_emergency_stop(forward_service_state_t* state, uint8_t reason_code) {
    if (state == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (reason_code > 1U) return AISOC_FWD_ERR_INVALID_ARG;
    const fwd_control_request request = {MINIMC_DEV_MC, MINIMC_CMD_MOTION_STOP, &reason_code, 1U, 0U};
    fwd_control_reply reply;
    pthread_mutex_lock(&state->uart_mutex);
    auto status = fwd_control_exchange_locked(state, &request, &reply);
    if (status == AISOC_FWD_OK) {
        usleep(45000);
        auto th_request = request;
        th_request.destination = MINIMC_DEV_SCM_TH;
        status = fwd_control_exchange_locked(state, &th_request, &reply);
    }
    pthread_mutex_unlock(&state->uart_mutex);
    return status;
}

aisoc_fwd_status_t forward_service_set_temperature(forward_service_state_t* state,
    uint8_t target_mask, const minimc_set_temp_req_t* request, minimc_temp_wire_payload_t* output) {
    if (state == nullptr || request == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (!valid_mask(target_mask)) return AISOC_FWD_ERR_INVALID_ARG;
    const uint8_t mask = target_mask == 0U ? 3U : target_mask;
    temperature_result results[2];
    size_t count = 0U;
    auto status = AISOC_FWD_OK;
    pthread_mutex_lock(&state->uart_mutex);
    for (uint8_t index = 0U; index < 2U; ++index) {
        if ((mask & (1U << index)) == 0U) continue;
        if (count > 0U) usleep(45000);
        status = set_temperature_node(state, static_cast<uint8_t>(2U + index), request, &results[count]);
        if (status != AISOC_FWD_OK) break;
        count += 1U;
    }
    pthread_mutex_unlock(&state->uart_mutex);
    // 保持未配置 writer 的内部诊断兼容；生产 writer 失败必须向上传播，不能重发硬件命令。
    auto publish_status = AISOC_FWD_OK;
    for (size_t index = 0U; index < count; ++index) {
        if (state->dds_pub_raw_temp == nullptr) break;
        if (aisoc_dds_publish_raw_temp(state->dds_pub_raw_temp, &results[index].sample) != AISOC_DDS_OK)
            publish_status = AISOC_FWD_ERR_DDS_PUBLISH;
    }
    if (status != AISOC_FWD_OK) return status;
    if (publish_status != AISOC_FWD_OK) return publish_status;
    *output = results[count - 1U].wire;
    return AISOC_FWD_OK;
}

