static void on_compat_reply(void* context, const fwd_comm_event_t* event) {
    if (context == nullptr || event == nullptr) return;
    auto* completion = static_cast<compat_completion*>(context);
    completion->sequence = event->sequence_id;
    completion->status = fwd_exchange_status(event->status);
    completion->reply.elapsed_ms = event->elapsed_ms;
    if (event->status != FWD_COMM_OK) return;
    if (event->response_cmd == MINIMC_CMD_ACK) {
        const bool reserved_ok = event->data[2] == 0U && event->data[3] == 0U;
        if (!reserved_ok || event->data[0] > 32U) {
            completion->status = AISOC_FWD_ERR_INVALID_ARG;
            return;
        }
    }
    completion->reply.rx_cmd = event->response_cmd;
    completion->reply.payload_len = event->data_len;
    std::memcpy(completion->reply.payload, event->data, event->data_len);
}

/**
 * @brief 兼容层串行访问共享事务，不再直接发送完整帧或建立私有等待循环。
 * @param state [in,out] 已初始化互斥锁的服务状态。
 * @param packet [in] 有界请求参数。
 * @param output [out] 可为空；仅成功时复制自有响应。
 * @return 第一次通信或ACK校验结果，不自动重试。
 */
static aisoc_fwd_status_t exchange_compat(forward_service_state_t* state,
    const compat_packet* packet, fwd_ctrl_rx_t* output) {
    if (state == nullptr || packet == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (!state->uart_mutex_initialized) return AISOC_FWD_ERR_INVALID_ARG;
    const bool status_query = packet->command == MINIMC_CMD_OTA_STATUS;
    const uint8_t response = status_query ? MINIMC_CMD_OTA_STATUS : MINIMC_CMD_ACK;
    const uint16_t response_size = status_query ? MINIMC_OTA_STATUS_RESP_SIZE : 4U;
    compat_completion completion;
    const fwd_exchange_spec spec = {
        {packet->command, response, static_cast<uint16_t>(packet->size), static_cast<uint16_t>(packet->size),
         response_size, response_size, true, MINIMC_CMD_NACK, 0U},
        {packet->destination, packet->command, packet->data, packet->size, packet->timeout_ms, 0U},
        on_compat_reply, &completion};
    pthread_mutex_lock(&state->uart_mutex);
    const auto result = fwd_exchange_locked(state, &spec);
    const auto status = result == AISOC_FWD_OK ? completion.status : result;
    if (status == AISOC_FWD_OK) {
        state->last_fault = {};
        if (output != nullptr) *output = completion.reply;
    } else {
        const fwd_ctrl_expect_t expect = {packet->destination, completion.sequence, response,
            response, response_size, packet->timeout_ms};
        fwd_control_record_fault(state, &expect, completion.reply.elapsed_ms, status);
    }
    pthread_mutex_unlock(&state->uart_mutex);
    return status;
}

aisoc_fwd_status_t forward_service_sys_control(forward_service_state_t* state,
    uint8_t dst_id, const minimc_payload_sys_ctrl_t* req) {
    if (state == nullptr || req == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    const compat_packet packet = {dst_id, MINIMC_CMD_SYSTEM_CONTROL,
        reinterpret_cast<const uint8_t*>(req), sizeof(*req), dst_id == MINIMC_DEV_SCM_TH ? 500U : 300U};
    return exchange_compat(state, &packet, nullptr);
}

aisoc_fwd_status_t forward_service_ota_start(forward_service_state_t* state,
    uint8_t dst_id, const minimc_payload_ota_start_t* req) {
    if (state == nullptr || req == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    const compat_packet packet = {dst_id, MINIMC_CMD_OTA_START,
        reinterpret_cast<const uint8_t*>(req), sizeof(*req), dst_id == MINIMC_DEV_SCM_TH ? 3000U : 2000U};
    return exchange_compat(state, &packet, nullptr);
}
