/**
 * @brief 处理 0x17 (EMERGENCY_STOP / MOTION_STOP) 紧急停止控制命令（支持单播回 4B ACK 与广播级联无 ACK）
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_motion_stop(uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    if (frame == NULL) { return; }
    const uint8_t dst_id = frame[3];
    const uint8_t flags = frame[4];
    if (plen > 1U)
    {
        if ((dst_id != 0xFFU) && ((flags & MINIMC_FLAG_WANTS_ACK) != 0U))
        {
            send_mc_nack(frame, seq, 0x02U);
        }
        return;
    }
    quickStop();
    Heater_set_target_temperature(&Extruder_One, 0);
    Heater_set_target_temperature(&Platform, 0);
    s_dbg_state.nozzle_set_ddC = 0;
    s_dbg_state.bed_set_ddC = 0;
    is_paused = ((plen >= 1U) && (frame[MINIMC_HEADER_SIZE] == 1U)) ? 1U : 0U;
    s_dbg_state.ack_seq = seq;
    mc_debug_notify_motion("STOP", 0U, 0U);
    if ((dst_id == 0xFFU) || ((flags & MINIMC_FLAG_WANTS_ACK) == 0U))
    {
        const bool can_flood = (dst_id == 0xFFU) && (frame[6] > 1U);
        const bool route_ok = ((frame[7] & 0x03U) != 0x03U);
        if (can_flood && route_ok)
        {
            const uint16_t f_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
            static uint8_t s_bcast_relay_buf[MINIMC_MAX_FRAME_SIZE];
            relay_frame(frame, f_len, s_bcast_relay_buf);
            (void)forward_uart_send_raw(s_bcast_relay_buf, f_len);
        }
        return;
    }
    minimc_ack_payload_t ack_pay;
    build_mc_ack_payload(&ack_pay);
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_ACK, seq, &ack_pay, sizeof(ack_pay));
    char kv[160];
    mc_dbg_format_motion_kv("STOP", kv, sizeof(kv));
    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq, MINIMC_CMD_ACK, "ACK" };
    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
}

