    { std::lock_guard<std::mutex> lk(st->mutex); st->maintenance = true; st->ota_rpc_code = -5; }
    no_dds_conn.request_refresh();
    const bool gate_allows_reprobe = sub_null_timed_out && wait_until([&]() {
        const auto snap = no_dds_conn.snapshot();
