static void record_exchange(forward_service_state_t* state, const fwd_comm_t* comm) {
    if (state == nullptr || comm == nullptr) return;
    const auto& event = comm->result;
    if (event.source_node != 0U) {
        if (state->receive_mutex_initialized) pthread_mutex_lock(&state->receive_mutex);
        state->rx_count += 1U;
        if (state->receive_mutex_initialized) pthread_mutex_unlock(&state->receive_mutex);
    }
    if (event.status == FWD_COMM_OK) return;
    std::fprintf(stderr, "[FWD QUERY] target_node=%u sequence_id=%u elapsed_ms=%u error_code=%d may_have_been_sent=%d\n",
        event.target_node, event.sequence_id, event.elapsed_ms,
        static_cast<int>(fwd_exchange_status(event.status)), event.may_have_been_sent);
}

/**
 * @brief 在事务锁内检查连接条件；旧兼容入口可初始化，新业务入口仅检查就绪状态。
 * @param state [in,out] 已持UART锁的通信所有者。
 * @param allow_open [in] 仅历史兼容包装允许打开；为假时禁止任何串口配置操作。
 * @return 就绪返回OK，否则立即返回错误，不隐式恢复连接。
 */
static aisoc_fwd_status_t prepare_connection(forward_service_state_t* state, bool allow_open) {
    if (state == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (!allow_open) {
        if (!state->serial_ctx.is_open || state->serial_ctx.fd < 0) return AISOC_FWD_ERR_SERIAL_OPEN;
        if (!state->receiver.initialized) return AISOC_FWD_ERR_INVALID_ARG;
        return AISOC_FWD_OK;
    }
    if (fwd_receive_ensure(state) != AISOC_FWD_OK) return AISOC_FWD_ERR_INVALID_ARG;
    return fwd_uart_open(state);
}

/**
 * @brief 单一事务实现；路由、组帧、序号、收发及响应关联都保留在通信层。
 * @param state [in,out] 已持UART锁的所有者。
 * @param spec [in] 请求及有界回调上下文。
 * @param allow_open [in] 历史包装的兼容策略，OTA不能指定。
 * @return 本次事务终态，不重发协议请求。
 */
aisoc_fwd_status_t fwd_exchange_drive(forward_service_state_t* state,
    const fwd_exchange_spec* spec, bool allow_open, fwd_comm_t* output) {
    if (state == nullptr || spec == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (state->io != nullptr && !fwd_io_is_owner(state)) return AISOC_FWD_ERR_BUSY;
    fwd_route_t route = {};
    if (fwd_router_lookup(&FWD_DEFAULT_ROUTES, spec->request.dst, &route) != FWD_COMM_OK)
        return AISOC_FWD_ERR_INVALID_ARG;
    if (route.link_id != FWD_UPLINK_UART) return AISOC_FWD_ERR_INVALID_ARG;
    const auto config = exchange_config(state, spec);
    auto& comm = *output;
    auto status = fwd_comm_init(&config, &comm);
    if (status != FWD_COMM_OK) return fwd_exchange_status(status);
    uint64_t request_id = 0U;
    const uint32_t start = spec->submitted_ms == 0U ? fwd_comm_serial_now_ms() : spec->submitted_ms;
    status = fwd_comm_send(&comm, &spec->request, start, &request_id);
    if (status != FWD_COMM_OK) return fwd_exchange_status(status);
    // 排队已耗尽预算时产生未发送终态，不打开端口或消耗服务序号。
    fwd_comm_tick(&comm, fwd_comm_serial_now_ms());
    if (comm.phase == fwd_comm_phase::DONE) return fwd_exchange_status(comm.result.status);
    const auto connection = prepare_connection(state, allow_open);
    if (connection != AISOC_FWD_OK) { comm.initialized = false; return connection; }
    // 通信对象完成参数检查后才改变所有者序号；驱动预算包含端口打开后的剩余时间。
    state->next_seq += 1U;
    comm.stop_requested = fwd_io_stopping;
    comm.stop_context = state;
    fwd_comm_serial_stats stats;
    const fwd_comm_serial_rx receive = {&state->receiver,
        state->receive_mutex_initialized ? &state->receive_mutex : nullptr};
    status = fwd_comm_run_serial(&comm, &state->serial_ctx, &stats, &receive);
    state->tx_count += stats.transmitted_frames;
    if (!state->serial_ctx.is_open) fwd_uart_close(state);
    record_exchange(state, &comm);
    return fwd_exchange_status(status);
}

