/**
 * @brief 解除已确认的急停锁；正交保留锁存前及锁存期上报的独立故障并广播真实前后状态
 * @param state 设备管理服务状态结构体指针
 */
static void clear_emergency_stop_state(device_manager_state_t* state) {
    if (state == nullptr) return;
    char old_state[32] = {}, new_state[32] = {};
    pthread_mutex_lock(&state->state_mutex);
    std::snprintf(old_state, sizeof(old_state), "%s", state->device_state);
    if (state->estop_latched) {
        state->is_fault = state->non_estop_fault;
    } else if (state->is_fault) {
        state->non_estop_fault = true;
    }
    state->estop_latched = false;
    state->estop_confirmed = false;
    std::snprintf(state->device_state, sizeof(state->device_state), "%s", state->is_fault ? "FAULT" : "IDLE");
    if (state->is_fault && std::strcmp(state->snapshot.system_status_desc, "EMERGENCY_STOP_INVOKED") == 0) {
        std::snprintf(state->snapshot.system_status_desc, sizeof(state->snapshot.system_status_desc), "FAULT");
    }
    dev_state_eval_freshness(state, get_host_monotonic_ns());
    state->generation_id += 1U;
    state->snapshot.generation_id = state->generation_id;
    std::snprintf(new_state, sizeof(new_state), "%s", state->device_state);
    pthread_mutex_unlock(&state->state_mutex);
    dev_dbus_emit_state_changed(state, old_state, new_state, "Emergency stop cleared");
}

/** @brief state为锁定对象；同步既有独立故障并先置本地未确认锁，下游超时仍保持本地保护。 */
static void latch_emergency_stop(device_manager_state_t* state) {
    if (state == nullptr) return;
    char old_state[32] = {};
    pthread_mutex_lock(&state->state_mutex);
    if (!state->estop_latched && state->is_fault) {
        state->non_estop_fault = true;
    }
    state->estop_latched = true;
    state->estop_confirmed = false;
    dev_state_set_fault(state, "EMERGENCY_STOP_INVOKED", old_state, sizeof(old_state));
    state->generation_id += 1U;
    state->snapshot.generation_id = state->generation_id;
    pthread_mutex_unlock(&state->state_mutex);
    dev_dbus_emit_state_changed(state, old_state, "FAULT", "Emergency stop requested");
}

/**
 * @brief 在 MC 与 TH 双板均返回 4B ACK 确认后置位 estop_confirmed 并推进快照世代号
 * @param state 设备管理服务状态结构体指针
 */
static void confirm_emergency_stop(device_manager_state_t* state) {
    if (state == nullptr) return;
    pthread_mutex_lock(&state->state_mutex);
    if (state->estop_latched) {
        state->estop_confirmed = true;
        state->generation_id += 1U;
        state->snapshot.generation_id = state->generation_id;
    }
    pthread_mutex_unlock(&state->state_mutex);
}

/**
 * @brief 在急停解除请求进入下游转发前撤销双板确认态，防止半程解除超时时误报双板仍确认急停
 * @param state 设备管理服务状态结构体指针
