 * @brief 在状态锁外广播维护态切换后的最新快照与 D-Bus 状态变化信号
 * @param state 设备管理服务状态结构体指针
 * @param snapshot 锁内复制的最新快照副本
 * @param old_state 切换前的设备状态字符串
 * @param entered true 表示进入维护态，false 表示退出维护态
 */
static void publish_maintenance_transition(
    device_manager_state_t* state,
    const aisoc_temp_snapshot_t* snapshot,
    const char* old_state,
    bool entered
) {
    if (state == nullptr || snapshot == nullptr || old_state == nullptr) return;
    if (state->dds_pub_snapshot != nullptr) {
        aisoc_dds_publish_temp_snapshot(state->dds_pub_snapshot, snapshot);
    }
    dev_dbus_emit_snapshot_updated(state, snapshot->generation_id, snapshot->timestamp_ns);
    dev_dbus_emit_state_changed(
        state,
        old_state,
        entered ? "UPGRADING_MAINTENANCE" : "IDLE",
        entered ? "OTA maintenance entered" : "OTA maintenance exited");
}

